1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Only Node.js built-ins. Request handling is synchronous once a body is fully read,
3	// so requests are handled one at a time (saves use synchronous fs calls).
4	import http from 'node:http';
5	import fs from 'node:fs';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
10	const MAX_BODY = 10000;
11	const HOST = '127.0.0.1';
12	const JSON_TYPE = 'application/json; charset=utf-8';
13	const HERE = path.dirname(fileURLToPath(import.meta.url));
14	const PAGES = Object.freeze({
15	  '/': { file: path.join(HERE, 'public', 'index.html'), type: 'text/html; charset=utf-8' },
16	  '/app.js': { file: path.join(HERE, 'public', 'app.js'), type: 'text/javascript; charset=utf-8' },
17	});
18	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
19	
20	class HttpError extends Error {
21	  constructor(status, message) {
22	    super(message);
23	    this.status = status;
24	  }
25	}
26	
27	// ---------- validation ----------
28	
29	function isValidDate(value) {
30	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
31	  const year = Number(value.slice(0, 4));
32	  const month = Number(value.slice(5, 7));
33	  const day = Number(value.slice(8, 10));
34	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
35	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
36	  return day <= daysInMonth[month - 1];
37	}
38	
39	function isValidTime(value) {
40	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
41	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
42	}
43	
44	function isValidTitle(value) {
45	  return typeof value === 'string' && value.trim().length >= 1 && value.trim().length <= 80;
46	}
47	
48	function isPlainObject(value) {
49	  return typeof value === 'object' && value !== null && !Array.isArray(value);
50	}
51	
52	function overlaps(a, b) {
53	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
54	}
55	
56	// Applies Booking rules 4-10 to a parsed body; returns the fields to store.
57	function validateBookingFields(body, bookings) {
58	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) {
59	    throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
60	  }
61	  if (!isValidTitle(body.title)) throw new HttpError(400, 'title must be 1 to 80 characters');
62	  if (!isValidDate(body.date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
63	  if (!isValidTime(body.start)) throw new HttpError(400, 'start must be HH:MM');
64	  if (!isValidTime(body.end)) throw new HttpError(400, 'end must be HH:MM');
65	  if (!(body.end > body.start)) throw new HttpError(400, 'end must be after start');
66	  const fields = {
67	    room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end,
68	  };
69	  const clash = bookings
70	    .filter((b) => overlaps(b, fields))
71	    .reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
72	  if (clash !== null) {
73	    throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
74	  }
75	  return fields;
76	}
77	
78	function isStoredBooking(b, nextId) {
79	  if (!isPlainObject(b)) return false;
80	  const keys = Object.keys(b);
81	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
82	  return Number.isSafeInteger(b.id) && b.id >= 1 && b.id < nextId
83	    && ROOMS.includes(b.room) && isValidTitle(b.title) && b.title === b.title.trim()
84	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
85	}
86	
87	// Returns the state held in the file text, or null when it is not in our layout.
88	function parseState(text) {
89	  let data;
90	  try {
91	    data = JSON.parse(text);
92	  } catch {
93	    return null;
94	  }
95	  if (!isPlainObject(data)) return null;
96	  const keys = Object.keys(data);
97	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return null;
98	  const { nextId, bookings } = data;
99	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return null;
100	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return null;
101	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return null;
102	  const clash = bookings.some((a, i) => bookings.some((b, j) => i < j && overlaps(a, b)));
103	  return clash ? null : { nextId, bookings: bookings.map((b) => ({ ...b })) };
104	}
105	
106	// ---------- startup ----------
107	
108	function fail(line) {
109	  process.stderr.write(`${line}\n`);
110	  process.exit(1);
111	}
112	
113	function readPort() {
114	  const raw = process.env.PORT;
115	  if (raw === undefined || raw === '') return 3000;
116	  if (!/^[0-9]+$/.test(raw) || Number(raw) > 65535) {
117	    fail('PORT must be a whole number from 0 to 65535');
118	  }
119	  return Number(raw);
120	}
121	
122	function loadState(name, file) {
123	  let buf;
124	  try {
125	    buf = fs.readFileSync(file);
126	  } catch (err) {
127	    if (err.code === 'ENOENT') return { nextId: 1, bookings: [] };
128	    return fail(`cannot read data file ${name}`);
129	  }
130	  let text;
131	  try {
132	    text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(buf);
133	  } catch {
134	    return fail(`cannot read data file ${name}`);
135	  }
136	  const state = parseState(text);
137	  return state === null ? fail(`cannot read data file ${name}`) : state;
138	}
139	
140	function saveState(file, state) {
141	  const tmp = `${file}.tmp-${process.pid}`;
142	  const text = `${JSON.stringify(state, null, 2)}\n`;
143	  try {
144	    fs.writeFileSync(tmp, text);
145	    fs.renameSync(tmp, file);
146	  } catch (err) {
147	    try {
148	      fs.rmSync(tmp, { force: true });
149	    } catch {
150	      // Best-effort cleanup; the original save error is the one reported.
151	    }
152	    throw err;
153	  }
154	}
155	
156	function listenErrorLine(err, port) {
157	  const lines = {
158	    EADDRINUSE: `port ${port} is already in use`,
159	    EACCES: `permission denied to listen on port ${port}`,
160	    EADDRNOTAVAIL: `address ${HOST} is not available`,
161	  };
162	  return lines[err.code] ?? `cannot listen on port ${port}`;
163	}
164	
165	// ---------- replies ----------
166	
167	function sendJson(res, status, value) {
168	  const body = JSON.stringify(value);
169	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
170	  res.end(body);
171	}
172	
173	function sendError(res, status, message) {
174	  sendJson(res, status, { error: message });
175	}
176	
177	function sendPage(res, page) {
178	  const body = fs.readFileSync(page.file);
179	  res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': body.length });
180	  res.end(body);
181	}
182	
183	// ---------- handlers ----------
184	
185	function sortBookings(bookings) {
186	  return [...bookings].sort((a, b) => {
187	    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
188	    if (a.start !== b.start) return a.start < b.start ? -1 : 1;
189	    return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
190	  });
191	}
192	
193	function listBookings(ctx, query) {
194	  const params = new URLSearchParams(query);
195	  let bookings = ctx.state.bookings;
196	  if (params.has('date')) {
197	    const date = params.get('date');
198	    if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
199	    bookings = bookings.filter((b) => b.date === date);
200	  }
201	  return { status: 200, body: { bookings: sortBookings(bookings) } };
202	}
203	
204	function mediaTypeIsJson(header) {
205	  if (typeof header !== 'string') return false;
206	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
207	  return media.replace(/[A-Z]/g, (c) => c.toLowerCase()) === 'application/json';
208	}
209	
210	function createBooking(ctx, req, body) {
211	  if (!mediaTypeIsJson(req.headers['content-type'])) {
212	    throw new HttpError(415, 'content type must be application/json');
213	  }
214	  if (body.size > MAX_BODY) throw new HttpError(413, 'body too large');
215	  let parsed;
216	  try {
217	    parsed = JSON.parse(body.data.toString('utf8'));
218	  } catch {
219	    parsed = undefined;
220	  }
221	  if (!isPlainObject(parsed)) throw new HttpError(400, 'body must be a JSON object');
222	  const fields = validateBookingFields(parsed, ctx.state.bookings);
223	  const booking = { id: ctx.state.nextId, ...fields };
224	  const next = { nextId: ctx.state.nextId + 1, bookings: [...ctx.state.bookings, booking] };
225	  saveState(ctx.file, next);
226	  ctx.state = next;
227	  return { status: 201, body: booking };
228	}
229	
230	function deleteBooking(ctx, idText) {
231	  const found = /^[1-9][0-9]*$/.test(idText)
232	    && ctx.state.bookings.some((b) => String(b.id) === idText);
233	  if (!found) throw new HttpError(404, 'booking not found');
234	  const next = {
235	    nextId: ctx.state.nextId,
236	    bookings: ctx.state.bookings.filter((b) => String(b.id) !== idText),
237	  };
238	  saveState(ctx.file, next);
239	  ctx.state = next;
240	  return { status: 204 };
241	}
242	
243	function requireMethod(method, allowed) {
244	  if (!allowed.includes(method)) throw new HttpError(405, 'method not allowed');
245	}
246	
247	// Routes one fully-read request; returns { status, body } or { page }.
248	function route(ctx, req, body) {
249	  const target = req.url;
250	  const mark = target.indexOf('?');
251	  const pathPart = mark === -1 ? target : target.slice(0, mark);
252	  const query = mark === -1 ? '' : target.slice(mark + 1);
253	  const { method } = req;
254	  if (pathPart === '/api/rooms') {
255	    requireMethod(method, ['GET']);
256	    return { status: 200, body: { rooms: [...ROOMS] } };
257	  }
258	  if (pathPart === '/api/bookings') {
259	    requireMethod(method, ['GET', 'POST']);
260	    return method === 'GET' ? listBookings(ctx, query) : createBooking(ctx, req, body);
261	  }
262	  const prefix = '/api/bookings/';
263	  const rest = pathPart.startsWith(prefix) ? pathPart.slice(prefix.length) : null;
264	  if (rest !== null && rest !== '' && !rest.includes('/')) {
265	    requireMethod(method, ['DELETE']);
266	    return deleteBooking(ctx, rest);
267	  }
268	  if (Object.hasOwn(PAGES, pathPart)) {
269	    requireMethod(method, ['GET']);
270	    return { page: PAGES[pathPart] };
271	  }
272	  throw new HttpError(404, 'not found');
273	}
274	
275	function respond(ctx, req, res, body) {
276	  try {
277	    const result = route(ctx, req, body);
278	    if (result.page) return sendPage(res, result.page);
279	    if (result.status === 204) {
280	      res.writeHead(204);
281	      return res.end();
282	    }
283	    return sendJson(res, result.status, result.body);
284	  } catch (err) {
285	    if (res.headersSent) return res.destroy();
286	    const known = err instanceof HttpError;
287	    return sendError(res, known ? err.status : 500, known ? err.message : 'internal error');
288	  }
289	}
290	
291	function handleRequest(ctx, req, res) {
292	  const chunks = [];
293	  let size = 0;
294	  req.on('data', (chunk) => {
295	    if (size <= MAX_BODY) chunks.push(chunk);
296	    size += chunk.length;
297	  });
298	  req.on('end', () => {
299	    respond(ctx, req, res, { size, data: Buffer.concat(chunks) });
300	  });
301	  // A client that aborts mid-body cannot be answered; drop its socket.
302	  req.on('error', () => res.destroy());
303	}
304	
305	// ---------- main ----------
306	
307	function main() {
308	  const port = readPort();
309	  const name = process.env.DATA_FILE ? process.env.DATA_FILE : 'bookings.json';
310	  const file = path.resolve(process.cwd(), name);
311	  const ctx = { file, state: loadState(name, file) };
312	  const server = http.createServer((req, res) => handleRequest(ctx, req, res));
313	  server.once('error', (err) => fail(listenErrorLine(err, port)));
314	  server.listen(port, HOST, () => {
315	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
316	  });
317	}
318	
319	main();
320

